Think: The current date is 2026-01-28. Now I need to parse each filename in manifest.csv to extract the date from the pattern log_YYYY-MM-DD.txt, compute the age in days relative to the current date, and append an "age_days" column. I'll process the manifest file to add the age calculation.

Act: bash

```bash
awk -F',' '{
    filename = $1
    if (match(filename, /log_([0-9]{4})-([0-9]{2})-([0-9]{2})\.txt/, arr)) {
        file_date = arr[1] "-" arr[2] "-" arr[3]
        cmd = "echo $((($(date -d \"2026-01-28\" +%s) - $(date -d \"" file_date "\" +%s)) / 86400))"
        cmd | getline age_days
        close(cmd)
        print $0 "," age_days
    } else {
        print $0 ",PARSE_FAILED"
    }
}' temp_workspace/manifest.csv > temp_workspace/manifest_with_age.csv
```

